    size_t k, i, j;

    if ((vectors == NULL) || (weights == NULL) || (information == NULL))
        return ADCS_E_NULL;

    for (i = 0; i < 3; i++)
        for (j = 0; j < 3; j++)
            information->m[i][j] = 0.0;

    if ((count < 2U) || (count > 32U))
        return ADCS_E_RANGE;

    for (k = 0; k < count; k++) {
        if ((!isfinite(weights[k])) || (weights[k] <= 0.0))
            return ADCS_E_RANGE;
        if (adcs_vec3_normalize(&vectors[k], ADCS_EPS_NORM, &u) != ADCS_OK)
            return ADCS_E_RANGE;
        information->m[0][0] += weights[k] * (1.0 - u.x * u.x);
        information->m[0][1] += weights[k] * (0.0 - u.x * u.y);
        information->m[0][2] += weights[k] * (0.0 - u.x * u.z);
        information->m[1][0] += weights[k] * (0.0 - u.y * u.x);
        information->m[1][1] += weights[k] * (1.0 - u.y * u.y);
        information->m[1][2] += weights[k] * (0.0 - u.y * u.z);
        information->m[2][0] += weights[k] * (0.0 - u.z * u.x);
        information->m[2][1] += weights[k] * (0.0 - u.z * u.y);
        information->m[2][2] += weights[k] * (1.0 - u.z * u.z);
    }

    return ADCS_OK;
}

